(239810, 14653, 3771, '<td valign="top">A bit of grain gives this photo a wonderful painterly quality--great colors and nice composition. Certainly says kitchen.</td>', 'A bit of grain gives this photo a wonderful painterly quality--great colors and nice composition. Certainly says kitchen.', '2003-03-18 02:03:03.000000', NULL, 1),
(239811, 14830, 3771, '<td valign="top">This one reaches out and grabs you.  Great reflections.  Composition might look a tad better if the pot were not quite so far to the right.  Beautiful pot.</td>', 'This one reaches out and grabs you.  Great reflections.  Composition might look a tad better if the pot were not quite so far to the right.  Beautiful pot.', '2003-03-18 02:09:10.000000', NULL, 1),
