(239830, 14742, 5728, '<td valign="top">Great idea, and the way you composed it is wonderful. I would be interested in knowing how you set this up.</td>', 'Great idea, and the way you composed it is wonderful. I would be interested in knowing how you set this up.', '2003-03-18 03:28:37.000000', NULL, 1),
(239832, 14506, 5728, '<td valign="top">The textures in the light shade give this photo a lot of impact. The light is not blown out at all, great capture.</td>', 'The textures in the light shade give this photo a lot of impact. The light is not blown out at all, great capture.', '2003-03-18 03:29:25.000000', NULL, 1),
(239845, 14788, 5728, '<td valign="top">Very well composed, I just love this photo. It''s one of my favourites for this challenge, you have set up the lighting perfectly here.</td>', 'Very well composed, I just love this photo. It''s one of my favourites for this challenge, you have set up the lighting perfectly here.', '2003-03-18 03:49:07.000000', NULL, 1),
(239846, 14839, 5728, '<td valign="top">Funny! Very well composed, the lighting is perfect and the body too :-)</td>', 'Funny! Very well composed, the lighting is perfect and the body too :-)', '2003-03-18 03:50:21.000000', NULL, 1),
(239847, 14720, 5728, '<td valign="top">Nice set up, my only nitpick is that the front of the photos is blurred but other than that, well done.</td>', 'Nice set up, my only nitpick is that the front of the photos is blurred but other than that, well done.', '2003-03-18 03:52:02.000000', NULL, 1),
(239848, 14445, 5728, '<td valign="top">Great shot, you really have an original idea here and you did it very well. Nice expression on the face, could almost fit into the emotion challenge as well :-)</td>', 'Great shot, you really have an original idea here and you did it very well. Nice expression on the face, could almost fit into the emotion challenge as well :-)', '2003-03-18 03:54:13.000000', NULL, 1),
(239849, 14637, 5728, '<td valign="top">Great setup and lighting. Well focused, I like the detail in this one.</td>', 'Great setup and lighting. Well focused, I like the detail in this one.', '2003-03-18 03:55:05.000000', NULL, 1),
(239890, 14669, 3306, '<td valign="top">Very colorful</td>', 'Very colorful', '2003-03-18 06:46:10.000000', NULL, 1),
(240127, 14879, 5728, '<td valign="top">Wow, this is so funny!! Those fish even look as if they have worried expressions on their faces. Congratulations on a wonderful shot.</td>', 'Wow, this is so funny!! Those fish even look as if they have worried expressions on their faces. Congratulations on a wonderful shot.', '2003-03-18 10:30:39.000000', NULL, 1),
(240130, 14934, 5728, '<td valign="top">Nice coloring! The reflection of the blue glass is awesome.</td>', 'Nice coloring! The reflection of the blue glass is awesome.', '2003-03-18 10:31:21.000000', NULL, 1),
(240133, 14923, 5728, '<td valign="top">Nice composition, I like the way you have the lighting here, no sign of glares or shadows.</td>', 'Nice composition, I like the way you have the lighting here, no sign of glares or shadows.', '2003-03-18 10:32:32.000000', NULL, 1),
(240197, 14278, 5728, '<td valign="top">I love the way the glass distorts those lines, great effect. It''s a very tight crop, but it works here, good one.</td>', 'I love the way the glass distorts those lines, great effect. It''s a very tight crop, but it works here, good one.', '2003-03-18 11:08:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(240199, 14858, 5728, '<td valign="top">You''ve created a nice effect with those shadows. It looks like a line of holes!</td>', 'You''ve created a nice effect with those shadows. It looks like a line of holes!', '2003-03-18 11:09:45.000000', NULL, 1),
(240206, 14769, 5728, '<td valign="top">That texture is pretty awesome! You got the lighting nearly perfect here, I like it.</td>', 'That texture is pretty awesome! You got the lighting nearly perfect here, I like it.', '2003-03-18 11:13:25.000000', NULL, 1),
(240211, 14774, 5728, '<td valign="top">Nice set up. It is well cropped and the way the outside glasses seem to be leaning outwards gives this image a nice effect.</td>', 'Nice set up. It is well cropped and the way the outside glasses seem to be leaning outwards gives this image a nice effect.', '2003-03-18 11:17:59.000000', NULL, 1),
(240214, 14607, 5728, '<td valign="top">Wonderful, nice effect. Clear glass and clear liquid always bring out a good image if done well like you have.</td>', 'Wonderful, nice effect. Clear glass and clear liquid always bring out a good image if done well like you have.', '2003-03-18 11:19:01.000000', NULL, 1),
(240230, 14869, 5728, '<td valign="top">You''ve made this look so fresh and juicy. And of course you''ve got me hungry, thank you! Excellent photo!</td>', 'You''ve made this look so fresh and juicy. And of course you''ve got me hungry, thank you! Excellent photo!', '2003-03-18 11:27:58.000000', NULL, 1),
(240284, 14835, 5865, '<td valign="top">Personally I think that the photograph would be improved if the only object in the frame was the strainer.  The other kitchen utensils seem to detract from the shot.  Nevertheless I think the lighting was superb and made for a very interesting still life.</td>', 'Personally I think that the photograph would be improved if the only object in the frame was the strainer.  The other kitchen utensils seem to detract from the shot.  Nevertheless I think the lighting was superb and made for a very interesting still life.', '2003-03-18 13:29:33.000000', NULL, 1),
(240285, 14813, 5865, '<td valign="top">A really beautiful shot. The lighting is great, but I can''t figure out where it is coming from.  I love it.</td>', 'A really beautiful shot. The lighting is great, but I can''t figure out where it is coming from.  I love it.', '2003-03-18 13:34:00.000000', NULL, 1),
(240291, 14608, 2279, '<td valign="top">Very nice. Tones are excellent plus focus and lighting are perfect. My pick for the week. 10.</td>', 'Very nice. Tones are excellent plus focus and lighting are perfect. My pick for the week. 10.', '2003-03-18 13:46:07.000000', NULL, 1),
(240293, 14839, 6855, '<td valign="top">Oh to be perky again...LOL!  Very creative and the water makes this an awesome shot!  I''m sure you have alot of "viewers" on this one, and what bachelor wouldn''t want this hanging in his kitchen????</td>', 'Oh to be perky again...LOL!  Very creative and the water makes this an awesome shot!  I''m sure you have alot of "viewers" on this one, and what bachelor wouldn''t want this hanging in his kitchen????', '2003-03-18 13:58:19.000000', NULL, 1),
(240294, 14722, 6855, '<td valign="top">CLEVER!  Interesting reflections in all te spoons and I like the tonal finish!  You must use cascade as I see no spots whatsoever!  LOL! 8 from me.</td>', 'CLEVER!  Interesting reflections in all te spoons and I like the tonal finish!  You must use cascade as I see no spots whatsoever!  LOL! 8 from me.', '2003-03-18 14:01:50.000000', NULL, 1),
(240296, 14283, 6855, '<td valign="top">Your lighting and focus on this is exceptional!  Th light glare in the onion is a distraction, but could definitely be fixed in a post-challenge edit.</td>', 'Your lighting and focus on this is exceptional!  Th light glare in the onion is a distraction, but could definitely be fixed in a post-challenge edit.', '2003-03-18 14:03:05.000000', NULL, 1),
(240298, 14706, 6855, '<td valign="top">Cute cute cute!  I could see this hanging in my kitchen.  The tonal finish is great and I love how it''s off-centered.  Lighting and focus are also perfect.  Very well done!</td>', 'Cute cute cute!  I could see this hanging in my kitchen.  The tonal finish is great and I love how it''s off-centered.  Lighting and focus are also perfect.  Very well done!', '2003-03-18 14:03:56.000000', NULL, 1),
(240303, 14847, 6855, '<td valign="top">This has the potential to be an awesome photo - the light glare is distrating and it has a snapshot feel to it - I know this could be great with some very minor cleaning up. Your angle is very fun, and your title is clever.</td>', 'This has the potential to be an awesome photo - the light glare is distrating and it has a snapshot feel to it - I know this could be great with some very minor cleaning up. Your angle is very fun, and your title is clever.', '2003-03-18 14:05:22.000000', NULL, 1),
(240307, 14858, 6855, '<td valign="top">This is so cute!  I love your angle, and you have great taste in dishes too! Pottery Barn????? LOL!</td>', 'This is so cute!  I love your angle, and you have great taste in dishes too! Pottery Barn????? LOL!', '2003-03-18 14:06:10.000000', NULL, 1),
(240310, 14778, 6855, '<td valign="top">I love the colors and angle on this!  The only thing I would change would be your DOF.</td>', 'I love the colors and angle on this!  The only thing I would change would be your DOF.', '2003-03-18 14:07:08.000000', NULL, 1),
(240316, 14923, 6855, '<td valign="top">Cool shot with great lighting - it does feel a little "washed" - I think you should have taken advantage of some shadows instead of trying to wash them so much.  This is still very clever, and I like your angle.</td>', 'Cool shot with great lighting - it does feel a little "washed" - I think you should have taken advantage of some shadows instead of trying to wash them so much.  This is still very clever, and I like your angle.', '2003-03-18 14:08:29.000000', NULL, 1),
(240320, 14374, 6855, '<td valign="top">I love your style.  This has an older, fun feel to it.  The focus is really off - I think you may have oversharpened it, but I''m sure the original is phenomenal.</td>', 'I love your style.  This has an older, fun feel to it.  The focus is really off - I think you may have oversharpened it, but I''m sure the original is phenomenal.', '2003-03-18 14:09:18.000000', NULL, 1),
(240326, 14742, 6855, '<td valign="top">I think this is the winner - I keep coming back to it over and over.  I love the angle of this, particularly because I don''t know how you accomplished it - self timer? Someone kneeling at chest level?? The fact that I have to keep guessing even improves the image.  I''ve been giving out plenty of 7s and 8s this week, but you are my first 10.  I''ll be VERY surprised if you don''t finish in the top 3.</td>', 'I think this is the winner - I keep coming back to it over and over.  I love the angle of this, particularly because I don''t know how you accomplished it - self timer? Someone kneeling at chest level?? The fact that I have to keep guessing even improves the image.  I''ve been giving out plenty of 7s and 8s this week, but you are my first 10.  I''ll be VERY surprised if you don''t finish in the top 3.', '2003-03-18 14:10:44.000000', NULL, 1),
(240329, 14604, 6855, '<td valign="top">LOVE your lighting, and I love old weathered feel to this.  Fabulous work!</td>', 'LOVE your lighting, and I love old weathered feel to this.  Fabulous work!', '2003-03-18 14:11:25.000000', NULL, 1),
(240332, 14866, 6855, '<td valign="top">Hilarious title!  I am trying to cut back on carbs, and talk about hard! You''re just making it harder - yum!! Great shot, but looks like you might have used the flash???</td>', 'Hilarious title!  I am trying to cut back on carbs, and talk about hard! You''re just making it harder - yum!! Great shot, but looks like you might have used the flash???', '2003-03-18 14:12:23.000000', NULL, 1),
(240337, 14941, 6855, '<td valign="top">LOL - great title and a great shot, although it does seel like your DOF is too shallow - the base of the glass is a little too blurry IMO, but this is still a fun shot.</td>', 'LOL - great title and a great shot, although it does seel like your DOF is too shallow - the base of the glass is a little too blurry IMO, but this is still a fun shot.', '2003-03-18 14:13:33.000000', NULL, 1),
(240349, 14637, 7211, '<td valign="top">if only there was a blue spice!  nicely done!</td>', 'if only there was a blue spice!  nicely done!', '2003-03-18 14:15:53.000000', NULL, 1),
(240353, 14887, 6855, '<td valign="top">WOW!!!! VERY CLEVER!!!! Do I dare ask how long it took you to make this??? This is really fabulous - you could start a wedding business - catering/photography all in one!  GREAT CREATIVE SHOT!</td>', 'WOW!!!! VERY CLEVER!!!! Do I dare ask how long it took you to make this??? This is really fabulous - you could start a wedding business - catering/photography all in one!  GREAT CREATIVE SHOT!', '2003-03-18 14:17:35.000000', NULL, 1),
