(241407, 14506, 5391, '<td valign="top">Clever and interesting.  Looks like the moon with eerie clouds around it.  Good reminder to look at everything from every angle when searching for creativity.</td>', 'Clever and interesting.  Looks like the moon with eerie clouds around it.  Good reminder to look at everything from every angle when searching for creativity.', '2003-03-19 12:30:24.000000', NULL, 1),
(241413, 14879, 1863, '<td valign="top">oh my, I hope you actually have a tank to keep these fish safe after taking the picture. It''s a bit ... too full, honestly. Bah, I wish I didn''t know this much about fish, but I do, and I have mixed feelings about this photo. I wish I could know that all of the fish are alive and well.</td>', 'oh my, I hope you actually have a tank to keep these fish safe after taking the picture. It''s a bit ... too full, honestly. Bah, I wish I didn''t know this much about fish, but I do, and I have mixed feelings about this photo. I wish I could know that all of the fish are alive and well.', '2003-03-19 12:41:35.000000', NULL, 1),
(241424, 14863, 1041, '<td valign="top">This shot is just phenomenal :)  I love all the textures and colors and I''m drooling heavily while typing this, and that despite the fact that I''ve only just finished lunch!  I could easily see this on the cover of a cooking magazine.  The only minor nitpick I have right now, and it''s not even a nitpick, but a suggestion, I guess, is to move the peppermill further to the right so that the fish doesn''t melt into it.</td>', 'This shot is just phenomenal :)  I love all the textures and colors and I''m drooling heavily while typing this, and that despite the fact that I''ve only just finished lunch!  I could easily see this on the cover of a cooking magazine.  The only minor nitpick I have right now, and it''s not even a nitpick, but a suggestion, I guess, is to move the peppermill further to the right so that the fish doesn''t melt into it.', '2003-03-19 12:54:10.000000', NULL, 1),
(241435, 14863, 3105, '<td valign="top">This is certainly making me hungry!  Nice presentation (for the meal)!  For the photo I might suggest a little more DOF to get the wine bottle and pepper mill into focus and to get the entire contents of the plate in focus too.</td>', 'This is certainly making me hungry!  Nice presentation (for the meal)!  For the photo I might suggest a little more DOF to get the wine bottle and pepper mill into focus and to get the entire contents of the plate in focus too.', '2003-03-19 13:10:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(241437, 14602, 1041, '<td valign="top">I love the soft colors on this one and the selective lighting.  The plain background and simple border just add to it.  One of my favorites this week :)</td>', 'I love the soft colors on this one and the selective lighting.  The plain background and simple border just add to it.  One of my favorites this week :)', '2003-03-19 13:11:22.000000', NULL, 1),
(241438, 14842, 1041, '<td valign="top">So simple and so effective.  Wonderful shot.  My top 3 this week.  :)</td>', 'So simple and so effective.  Wonderful shot.  My top 3 this week.  :)', '2003-03-19 13:11:43.000000', NULL, 1),
(241442, 14778, 4543, '<td valign="top">I would have like the 2 cups or bowl in front in full focus.  Overall, great work and nice composition. 6.</td>', 'I would have like the 2 cups or bowl in front in full focus.  Overall, great work and nice composition. 6.', '2003-03-19 13:21:51.000000', NULL, 1),
(241443, 14887, 4543, '<td valign="top">This is great effort, wonderful composition and nice border. 8.</td>', 'This is great effort, wonderful composition and nice border. 8.', '2003-03-19 13:22:51.000000', NULL, 1),
(241444, 14769, 4543, '<td valign="top">I''m having a hard time to think what this is, anyway, its a great abstract photo. 6.</td>', 'I''m having a hard time to think what this is, anyway, its a great abstract photo. 6.', '2003-03-19 13:25:08.000000', NULL, 1),
(241445, 14912, 1041, '<td valign="top">Hi Paul :)  Is this really a cheese-grater?  Certainly different from others I have seen.  Live and learn.  Well, I like the angle in your photo a lot, but the two things I find pretty distracting are the shadow on your background (moving the grater further away or using alternate lighting could help) and the wrinkles and stains (above the part that fixes the grater to the base) are distracting.  I like the border you''ve added to the photo.</td>', 'Hi Paul :)  Is this really a cheese-grater?  Certainly different from others I have seen.  Live and learn.  Well, I like the angle in your photo a lot, but the two things I find pretty distracting are the shadow on your background (moving the grater further away or using alternate lighting could help) and the wrinkles and stains (above the part that fixes the grater to the base) are distracting.  I like the border you''ve added to the photo.', '2003-03-19 13:25:59.000000', NULL, 1),
(241447, 14839, 4543, '<td valign="top">Very nice.  Artistically and technically flawless. 9.</td>', 'Very nice.  Artistically and technically flawless. 9.', '2003-03-19 13:29:14.000000', NULL, 1),
(241448, 14349, 1041, '<td valign="top">Cool teapot and cup.  :)  Great for this photo, funny title, too.  Two main things that I think would improve your photo are the focus (the image seems overall soft) and to clean up some of the clutter in the background (the cooling rack and salt/pepper shaker) to make sure the user is really focused on your main objects, and not on what''s in the background.</td>', 'Cool teapot and cup.  :)  Great for this photo, funny title, too.  Two main things that I think would improve your photo are the focus (the image seems overall soft) and to clean up some of the clutter in the background (the cooling rack and salt/pepper shaker) to make sure the user is really focused on your main objects, and not on what''s in the background.', '2003-03-19 13:29:59.000000', NULL, 1),
(241449, 14653, 4543, '<td valign="top">Nice work. 7.</td>', 'Nice work. 7.', '2003-03-19 13:30:17.000000', NULL, 1),
(241452, 14841, 3105, '<td valign="top">Very nice compostion.  Having the ingredients and the measuring spoons only partially on the outskirts of the frame while the bowl is completely shown is an excellent way to draw the eye around the various pieces of the photo while keeping you focused on the overall image itself.  Wonderful, and it''s making me want to make some cookies!<br/>Score: 10</td>', 'Very nice compostion.  Having the ingredients and the measuring spoons only partially on the outskirts of the frame while the bowl is completely shown is an excellent way to draw the eye around the various pieces of the photo while keeping you focused on the overall image itself.  Wonderful, and it''s making me want to make some cookies!Score: 10', '2003-03-19 13:39:37.000000', NULL, 1),
(241454, 14901, 3105, '<td valign="top">Nice focus and clarity.  For my tastes the DOF might be a hair to shallow because the front apples and the basket facing the camera looks a bit out of focus.  It''s not a big thing but for a still life shot like this where the subject occupies the entire frame and at such an angle, my eyes look around for uniform focus. (hope you don''t think I''m being nitpicky)<br/>Score: 8</td>', 'Nice focus and clarity.  For my tastes the DOF might be a hair to shallow because the front apples and the basket facing the camera looks a bit out of focus.  It''s not a big thing but for a still life shot like this where the subject occupies the entire frame and at such an angle, my eyes look around for uniform focus. (hope you don''t think I''m being nitpicky)Score: 8', '2003-03-19 13:48:15.000000', NULL, 1),
(241461, 14297, 3105, '<td valign="top">Is that just food coloring?  I wonder if this is how Jackson Pollock got his start.  Cool idea.</td>', 'Is that just food coloring?  I wonder if this is how Jackson Pollock got his start.  Cool idea.', '2003-03-19 13:53:05.000000', NULL, 1),
(241464, 14608, 3105, '<td valign="top">This is really nice.  Great effect of the pot and background being the same tones while the shadows help define the pot.  Good job!  Love the crack (?) in the corner too.<br/>Score: 10</td>', 'This is really nice.  Great effect of the pot and background being the same tones while the shadows help define the pot.  Good job!  Love the crack (?) in the corner too.Score: 10', '2003-03-19 13:56:09.000000', NULL, 1),
(241478, 14809, 3105, '<td valign="top">Nice shot.  I like the color effects of the blue and yellow.  The front does seem a bit underlit though.  I might like to see it lit with a bit of soft white light from the front to see if it pulls more highlights off the metal peices.  Would probably have to be quite diffused.<br/>Score: 7</td>', 'Nice shot.  I like the color effects of the blue and yellow.  The front does seem a bit underlit though.  I might like to see it lit with a bit of soft white light from the front to see if it pulls more highlights off the metal peices.  Would probably have to be quite diffused.Score: 7', '2003-03-19 14:07:29.000000', NULL, 1),
(241486, 14765, 3105, '<td valign="top">Simple yet really cool.  Love the color and composition.<br/>Score: 8</td>', 'Simple yet really cool.  Love the color and composition.Score: 8', '2003-03-19 14:11:18.000000', NULL, 1),
(241502, 14827, 3105, '<td valign="top">Boy, wouldn''t that be a surprise to wake up to that "breakfast" during the honeymoon.  Nice subject and composition.  Good, even lighting too.<br/>Score: 7</td>', 'Boy, wouldn''t that be a surprise to wake up to that "breakfast" during the honeymoon.  Nice subject and composition.  Good, even lighting too.Score: 7', '2003-03-19 14:18:22.000000', NULL, 1),
(241506, 14852, 3105, '<td valign="top">Really cool shot.  I imagine this was done with a long(ish) exposure to get that clarity.  Love the blue effect of the metal reflections - it really makes the heating elements pop out.  Great shot!<br/>Score: 10</td>', 'Really cool shot.  I imagine this was done with a long(ish) exposure to get that clarity.  Love the blue effect of the metal reflections - it really makes the heating elements pop out.  Great shot!Score: 10', '2003-03-19 14:22:01.000000', NULL, 1),
(241510, 14672, 3105, '<td valign="top">I''m wondering if this was shot handheld with no flash.  It is rather blurry.  It looks like it could use either a tripod to stabalize for a longer exposure or more lighting to allow for a faster shutter speed.  I like the mascot though.  Makes me thirsty.</td>', 'I''m wondering if this was shot handheld with no flash.  It is rather blurry.  It looks like it could use either a tripod to stabalize for a longer exposure or more lighting to allow for a faster shutter speed.  I like the mascot though.  Makes me thirsty.', '2003-03-19 14:26:20.000000', NULL, 1),
(241511, 14692, 3105, '<td valign="top">Nice sharp shot.  Either your camera has excellent white balance settings or your color corrections in post are spot on.</td>', 'Nice sharp shot.  Either your camera has excellent white balance settings or your color corrections in post are spot on.', '2003-03-19 14:29:22.000000', NULL, 1),
(241551, 14813, 811, '<td valign="top">I absolutely love this picture, and everything about it -- the focus, the lighting, and coloring.  Looks like a shot for Southern Living or Good Housekeeping magazine!<br/></td>', 'I absolutely love this picture, and everything about it -- the focus, the lighting, and coloring.  Looks like a shot for Southern Living or Good Housekeeping magazine!', '2003-03-19 15:50:11.000000', NULL, 1),
(241552, 14809, 811, '<td valign="top">This would look super hanging on the wall of a modern kitchen.  I really like the bright and contrasting colors.  Wonderful.</td>', 'This would look super hanging on the wall of a modern kitchen.  I really like the bright and contrasting colors.  Wonderful.', '2003-03-19 15:50:46.000000', NULL, 1),
(241555, 14602, 811, '<td valign="top">A very elegant shot of a very simple subject.  You have lit this in and astoundingly remarkably and effective way.  Good work.</td>', 'A very elegant shot of a very simple subject.  You have lit this in and astoundingly remarkably and effective way.  Good work.', '2003-03-19 15:51:21.000000', NULL, 1),
(241556, 14684, 811, '<td valign="top">I like the composition of this, and how the fruit gives the eyes a place to rest. Very nicely done.</td>', 'I like the composition of this, and how the fruit gives the eyes a place to rest. Very nicely done.', '2003-03-19 15:51:49.000000', NULL, 1),
(241557, 14940, 811, '<td valign="top">I love the contrast of the faucet and blinds.  The coloring is very attention grabbing.  One teeny-weeny nit -- I can see you!</td>', 'I love the contrast of the faucet and blinds.  The coloring is very attention grabbing.  One teeny-weeny nit -- I can see you!', '2003-03-19 15:52:26.000000', NULL, 1),
(241558, 14852, 811, '<td valign="top">I love the colors and composition of this.  Everytime I look at my toaster I think of this shot.  Great work!</td>', 'I love the colors and composition of this.  Everytime I look at my toaster I think of this shot.  Great work!', '2003-03-19 15:53:00.000000', NULL, 1),
(241559, 14887, 811, '<td valign="top">Beautiful.  I love the contrasting colors.</td>', 'Beautiful.  I love the contrasting colors.', '2003-03-19 15:53:17.000000', NULL, 1),
(241560, 14896, 811, '<td valign="top">The blue, in addition to the texture, really gives this abstract a neat feeling.  Great work.</td>', 'The blue, in addition to the texture, really gives this abstract a neat feeling.  Great work.', '2003-03-19 15:53:43.000000', NULL, 1),
(241561, 14866, 811, '<td valign="top">Boy, I pity those on the Atkins'' Diet.  Of course, we on the Weight Watchers Program would have difficulty with this one as well.  Great focus.  maybe a touch busy -- perhaps you could have isolated one piece and shot it.  Otherwise, why don''t you send me a piece of it!</td>', 'Boy, I pity those on the Atkins'' Diet.  Of course, we on the Weight Watchers Program would have difficulty with this one as well.  Great focus.  maybe a touch busy -- perhaps you could have isolated one piece and shot it.  Otherwise, why don''t you send me a piece of it!', '2003-03-19 15:54:52.000000', NULL, 1),
(241562, 14788, 811, '<td valign="top">Such a simple shot.  The diagonal pasta really adds interest and dynamics to this!</td>', 'Such a simple shot.  The diagonal pasta really adds interest and dynamics to this!', '2003-03-19 15:55:18.000000', NULL, 1),
(241563, 14806, 811, '<td valign="top">Great use of lighting and shadows</td>', 'Great use of lighting and shadows', '2003-03-19 15:55:31.000000', NULL, 1),
(241564, 14637, 811, '<td valign="top">So simple and effective.  Would make a nice print, I think.</td>', 'So simple and effective.  Would make a nice print, I think.', '2003-03-19 15:55:50.000000', NULL, 1),
(241566, 14842, 811, '<td valign="top">I like the simplicity of this.  Great take on the theme.</td>', 'I like the simplicity of this.  Great take on the theme.', '2003-03-19 15:56:16.000000', NULL, 1),
(241689, 14672, 1041, '<td valign="top">Cute, but slightly soft/out of focus.</td>', 'Cute, but slightly soft/out of focus.', '2003-03-19 18:10:38.000000', NULL, 1),
(241690, 14835, 1041, '<td valign="top">Good idea, I like shadow plays.  Removing the knife block in the background would make the background even less obtrusive.</td>', 'Good idea, I like shadow plays.  Removing the knife block in the background would make the background even less obtrusive.', '2003-03-19 18:12:05.000000', NULL, 1),
(241713, 14507, 3575, '<td valign="top">A pair of pears - Nice reflection.</td>', 'A pair of pears - Nice reflection.', '2003-03-19 18:37:31.000000', NULL, 1),
(241719, 14637, 3575, '<td valign="top">I am impressed, you didn''t spill any! Very nice and simple and clean - I like this a lot.</td>', 'I am impressed, you didn''t spill any! Very nice and simple and clean - I like this a lot.', '2003-03-19 18:39:21.000000', NULL, 1),
(241721, 14297, 3575, '<td valign="top">Somebody had fun. Very cleaver idea!</td>', 'Somebody had fun. Very cleaver idea!', '2003-03-19 18:40:32.000000', NULL, 1),
(241726, 14887, 3575, '<td valign="top">OMG, I don''t know if you did the cutting, you ARE multitalented. Very well photographed. I like the composition and the blue background.</td>', 'OMG, I don''t know if you did the cutting, you ARE multitalented. Very well photographed. I like the composition and the blue background.', '2003-03-19 18:43:55.000000', NULL, 1),
(241729, 14813, 3575, '<td valign="top">A wonderful scene! I''m going back and forth about the table cloth though, I know that I would have left it straight but that''s because I neurotic.  Nevertheless, the sepia tone is beautiful and I just want to sit there and have a cup of coffee and toast, it''s very inviting.</td>', 'A wonderful scene! I''m going back and forth about the table cloth though, I know that I would have left it straight but that''s because I neurotic.  Nevertheless, the sepia tone is beautiful and I just want to sit there and have a cup of coffee and toast, it''s very inviting.', '2003-03-19 18:47:24.000000', NULL, 1),
(241732, 14927, 3575, '<td valign="top">I like the idea and I like that you made it b &amp; w but it is a little too dark. It is also isn''t straight but I think the problem is it''s skewed so just rotating wouldn''t help much.</td>', 'I like the idea and I like that you made it b & w but it is a little too dark. It is also isn''t straight but I think the problem is it''s skewed so just rotating wouldn''t help much.', '2003-03-19 18:56:28.000000', NULL, 1),
(241733, 14874, 3575, '<td valign="top">mmmmm Very nice close-up. It''s so vivid I can almost smell it.</td>', 'mmmmm Very nice close-up. It''s so vivid I can almost smell it.', '2003-03-19 18:57:13.000000', NULL, 1),
(241735, 14841, 3575, '<td valign="top">This is a wonderfully photographed scene. Please don''t hate me but I don''t like the angle. With this much going on, one has to actually cock ones head to look at it. Rocky Road Brownies sounds delish!</td>', 'This is a wonderfully photographed scene. Please don''t hate me but I don''t like the angle. With this much going on, one has to actually cock ones head to look at it. Rocky Road Brownies sounds delish!', '2003-03-19 18:59:44.000000', NULL, 1),
(241737, 14852, 3575, '<td valign="top">Perfect! This is really artistic. I love the blue chrome and I believe your toaster isn''t naturally blue, right? This is great!</td>', 'Perfect! This is really artistic. I love the blue chrome and I believe your toaster isn''t naturally blue, right? This is great!', '2003-03-19 19:01:00.000000', NULL, 1),
(241739, 14835, 3575, '<td valign="top">I like this a lot. I would have liked it a lot better with a stainless colander for the reason that you have a wood counter, natural sunlight, and something else natural looking in the background and the plastic colander just doesn''t fit in the otherwise natural looking scene. But, that said, it is a well done photo, nicely composed and excellent use of natural light.</td>', 'I like this a lot. I would have liked it a lot better with a stainless colander for the reason that you have a wood counter, natural sunlight, and something else natural looking in the background and the plastic colander just doesn''t fit in the otherwise natural looking scene. But, that said, it is a well done photo, nicely composed and excellent use of natural light.', '2003-03-19 19:05:25.000000', NULL, 1),
(241741, 14827, 3575, '<td valign="top">LOL, That would be a mess! Love the black surface and bg and I like the cord pulled around the front, it adds a nice detail. It looks like it''s tilted just a little to the clockwise but that could be just an illusion.</td>', 'LOL, That would be a mess! Love the black surface and bg and I like the cord pulled around the front, it adds a nice detail. It looks like it''s tilted just a little to the clockwise but that could be just an illusion.', '2003-03-19 19:08:56.000000', NULL, 1),
(241743, 14607, 3575, '<td valign="top">Very nice. I love the graduated background and the sepia tone. Perfectly placed object. Nice, clean, sharp.</td>', 'Very nice. I love the graduated background and the sepia tone. Perfectly placed object. Nice, clean, sharp.', '2003-03-19 19:11:00.000000', NULL, 1),
(241744, 14856, 3575, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2003-03-19 19:13:45.000000', NULL, 1),
(241745, 14839, 3575, '<td valign="top">I really find this photo disgusting simply because I don''t look like that anymore! Actually, It''s a very nice photograph. I love the tone on tone of the pepper grinder, her bronze skin and the gold wall. Everything works very well together. Excuse me while I go do some sit ups....</td>', 'I really find this photo disgusting simply because I don''t look like that anymore! Actually, It''s a very nice photograph. I love the tone on tone of the pepper grinder, her bronze skin and the gold wall. Everything works very well together. Excuse me while I go do some sit ups....', '2003-03-19 19:15:54.000000', NULL, 1),
(241748, 14778, 3575, '<td valign="top">I would love these dishes at home! Simple photo, nice use of DOF and well composed. Good job.</td>', 'I would love these dishes at home! Simple photo, nice use of DOF and well composed. Good job.', '2003-03-19 19:16:50.000000', NULL, 1),
(241750, 14941, 3575, '<td valign="top">Wow, it''s amazing what a camera can catch. That looks sooo good and refreshing. I have to check back to get the details of your settings, I can tell you had a larger aperature because of the narrow DOF but I want to know the shutter speed that would freeze this so perfectly. Nice job.</td>', 'Wow, it''s amazing what a camera can catch. That looks sooo good and refreshing. I have to check back to get the details of your settings, I can tell you had a larger aperature because of the narrow DOF but I want to know the shutter speed that would freeze this so perfectly. Nice job.', '2003-03-19 19:19:26.000000', NULL, 1),
(241752, 14604, 3575, '<td valign="top">A work of art. You found the most amazing object and then your decision to photograph it on a dirt surface is genius. It looks like it was just excavated. I have only one suggestion and that is to try to get the entire tureen in focus. The upper part of the lid is just a little soft.</td>', 'A work of art. You found the most amazing object and then your decision to photograph it on a dirt surface is genius. It looks like it was just excavated. I have only one suggestion and that is to try to get the entire tureen in focus. The upper part of the lid is just a little soft.', '2003-03-19 19:22:48.000000', NULL, 1),
(241753, 14806, 3575, '<td valign="top">Excellent DOF, The cork is just as clear and sharp as the screw. Wonderful lighting and I like the effect the light has on the bg giving it a graduated effect.</td>', 'Excellent DOF, The cork is just as clear and sharp as the screw. Wonderful lighting and I like the effect the light has on the bg giving it a graduated effect.', '2003-03-19 19:25:53.000000', NULL, 1),
(241754, 14445, 3575, '<td valign="top">Very Clever!</td>', 'Very Clever!', '2003-03-19 19:26:37.000000', NULL, 1),
(241755, 14809, 3575, '<td valign="top">Beautiful. One of my favorites this week.</td>', 'Beautiful. One of my favorites this week.', '2003-03-19 19:28:24.000000', NULL, 1),
(241756, 14929, 3575, '<td valign="top">Excellent capture of the steam! Of course, I would think that the pot would be a little too hot to hold like that. I like the purplish tone.</td>', 'Excellent capture of the steam! Of course, I would think that the pot would be a little too hot to hold like that. I like the purplish tone.', '2003-03-19 19:29:34.000000', NULL, 1),
