(241851, 14756, 7190, '<td valign="top">clever</td>', 'clever', '2003-03-19 21:57:44.000000', NULL, 1),
(241863, 14682, 7190, '<td valign="top">I found this a bit confusing too much going on. i would have concentrated on the chili''s in bottle on the left and/or  the black heat bottle.</td>', 'I found this a bit confusing too much going on. i would have concentrated on the chili''s in bottle on the left and/or  the black heat bottle.', '2003-03-19 22:08:34.000000', NULL, 1),
