(243507, 14607, 3102, '<td valign="top">Super!  You did a great job of capturing a sharp image -- the toning and lighting is also quite well done.</td>', 'Super!  You did a great job of capturing a sharp image -- the toning and lighting is also quite well done.', '2003-03-23 14:07:47.000000', NULL, 1),
(243508, 14841, 3102, '<td valign="top">Looks like it came right out of a cook book -- this looks like something that has a lot of potential as a print!  Great toning, and the angle adds a lot of interest to the shot.</td>', 'Looks like it came right out of a cook book -- this looks like something that has a lot of potential as a print!  Great toning, and the angle adds a lot of interest to the shot.', '2003-03-23 14:09:03.000000', NULL, 1),
