(243510, 14602, 3102, '<td valign="top">My breath is getting smelly just from looking at this shot :)  Seriuosly, it''s an excellent shot with supurb lighting.</td>', 'My breath is getting smelly just from looking at this shot :)  Seriuosly, it''s an excellent shot with supurb lighting.', '2003-03-23 14:10:29.000000', NULL, 1),
(243511, 14896, 3102, '<td valign="top">Neat shot!  Very well executed.  I''m betting it took a lot of work to pull this one off.</td>', 'Neat shot!  Very well executed.  I''m betting it took a lot of work to pull this one off.', '2003-03-23 14:11:22.000000', NULL, 1),
(243512, 14774, 3102, '<td valign="top">Excellent colors and details!  I would have bumped this up by a point if the foreground had been in perfect focus.</td>', 'Excellent colors and details!  I would have bumped this up by a point if the foreground had been in perfect focus.', '2003-03-23 14:12:28.000000', NULL, 1),
(243515, 14604, 3102, '<td valign="top">Great shot!  Reminds me of artifacts we got to see while touring Pompeii!  I''ll be interested in reading the details on this one.</td>', 'Great shot!  Reminds me of artifacts we got to see while touring Pompeii!  I''ll be interested in reading the details on this one.', '2003-03-23 14:13:47.000000', NULL, 1),
(243516, 14806, 3102, '<td valign="top">Great use of shadows -- well done!  It looks like it may have been sharpened just a teeny bit too much, but otherwise it''s outstanding.</td>', 'Great use of shadows -- well done!  It looks like it may have been sharpened just a teeny bit too much, but otherwise it''s outstanding.', '2003-03-23 14:15:04.000000', NULL, 1),
(243518, 14939, 3102, '<td valign="top">Overall a well-done shot that''s hard to pull off.  I''m not sure if I like the way the colors were desaturated as it left the shot a little "chunky" but it''s still a nice effort.</td>', 'Overall a well-done shot that''s hard to pull off.  I''m not sure if I like the way the colors were desaturated as it left the shot a little "chunky" but it''s still a nice effort.', '2003-03-23 14:16:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(243519, 14506, 3102, '<td valign="top">It''s a bit abstract for the challenge, in my opinion.</td>', 'It''s a bit abstract for the challenge, in my opinion.', '2003-03-23 14:17:19.000000', NULL, 1),
(243521, 14889, 3102, '<td valign="top">I think this may have been stronger if the whole whisk had been in focus.</td>', 'I think this may have been stronger if the whole whisk had been in focus.', '2003-03-23 14:20:09.000000', NULL, 1),
(243522, 14940, 3102, '<td valign="top">A very interesting concept, carried out quite well!  I''d be curious to see what it would have looked like had the blinds been in focus, too.  And it would probably have been better to somehow eliminiate your reflection from the faucet, too.</td>', 'A very interesting concept, carried out quite well!  I''d be curious to see what it would have looked like had the blinds been in focus, too.  And it would probably have been better to somehow eliminiate your reflection from the faucet, too.', '2003-03-23 14:21:51.000000', NULL, 1),
(243523, 14349, 3102, '<td valign="top">The focus is a little soft for my taste, but it''s a cute image.</td>', 'The focus is a little soft for my taste, but it''s a cute image.', '2003-03-23 14:22:42.000000', NULL, 1),
